import{_ as t,o as d,c as o,aU as a}from"./chunks/framework.BWaOKJaB.js";const g=JSON.parse('{"title":"编程技巧总结","description":"","frontmatter":{},"headers":[],"relativePath":"技术/前端/编程技巧.md","filePath":"03.技术/01.前端/08.编程技巧.md","lastUpdated":0}'),l={name:"技术/前端/编程技巧.md"};function r(c,e,i,n,s,h){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="编程技巧总结" tabindex="-1">编程技巧总结 <a class="header-anchor" href="#编程技巧总结" aria-label="Permalink to “编程技巧总结”">​</a></h1><h2 id="vs-code-中-html-与-emmet-快捷编写" tabindex="-1">VS Code 中 HTML 与 Emmet 快捷编写 <a class="header-anchor" href="#vs-code-中-html-与-emmet-快捷编写" aria-label="Permalink to “VS Code 中 HTML 与 Emmet 快捷编写”">​</a></h2><p>在 VS Code 里写 HTML，最常用的是 <strong>Emmet</strong>（已内置，一般不用单独装）。在 <code>.html</code> 或支持 Emmet 的文件里输入缩写，按 <strong>Tab</strong>（或设置里绑定的 <strong>Emmet 展开</strong> 键，有时是 Enter）即可展开成标签。</p><h3 id="标签-class-id" tabindex="-1">标签 + class / id <a class="header-anchor" href="#标签-class-id" aria-label="Permalink to “标签 + class / id”">​</a></h3><table tabindex="0"><thead><tr><th>输入</th><th>展开大致为</th></tr></thead><tbody><tr><td><code>div</code></td><td><code>&lt;div&gt;&lt;/div&gt;</code></td></tr><tr><td><code>div.wrap</code></td><td><code>&lt;div class=&quot;wrap&quot;&gt;&lt;/div&gt;</code></td></tr><tr><td><code>div#main</code></td><td><code>&lt;div id=&quot;main&quot;&gt;&lt;/div&gt;</code></td></tr><tr><td><code>p.note.error</code></td><td><code>&lt;p class=&quot;note error&quot;&gt;&lt;/p&gt;</code></td></tr></tbody></table><p>多个 class 用 <code>.</code> 连在一起即可。</p><h3 id="子级、同级、上级" tabindex="-1">子级、同级、上级 <a class="header-anchor" href="#子级、同级、上级" aria-label="Permalink to “子级、同级、上级”">​</a></h3><table tabindex="0"><thead><tr><th>含义</th><th>写法</th><th>示例效果</th></tr></thead><tbody><tr><td>子元素</td><td><code>&gt;</code></td><td><code>nav&gt;ul&gt;li</code> → nav 里 ul，ul 里 li</td></tr><tr><td>兄弟</td><td><code>+</code></td><td><code>div+p</code> → 两个并列标签</td></tr><tr><td>上一级</td><td><code>^</code></td><td><code>div&gt;p^footer</code> → p 在 div 里，footer 与 div 同级</td></tr></tbody></table><h3 id="重复-列表常用" tabindex="-1">重复（列表常用） <a class="header-anchor" href="#重复-列表常用" aria-label="Permalink to “重复（列表常用）”">​</a></h3><ul><li><code>ul&gt;li*5</code> → 5 个 <code>&lt;li&gt;</code></li><li><code>div.item*3</code> → 3 个带 <code>class=&quot;item&quot;</code> 的 div</li></ul><h3 id="属性" tabindex="-1">属性 <a class="header-anchor" href="#属性" aria-label="Permalink to “属性”">​</a></h3><ul><li><code>a[href=# title=首页]</code> → 带 <code>href</code>、<code>title</code> 的 <code>&lt;a&gt;</code></li><li><code>input[type=text]</code> → 对应属性</li></ul><h3 id="假文-lorem" tabindex="-1">假文（Lorem） <a class="header-anchor" href="#假文-lorem" aria-label="Permalink to “假文（Lorem）”">​</a></h3><ul><li><code>lorem</code> → 一段默认长度的占位文</li><li><code>lorem10</code> → 约 10 个词（数字可改）</li><li><code>p&gt;lorem</code> → 段落里包一段 lorem</li></ul><p>具体词数可能随 Emmet 版本略有差异，以编辑器里实际展开为准。</p><h3 id="隐式标签名-可选" tabindex="-1">隐式标签名（可选） <a class="header-anchor" href="#隐式标签名-可选" aria-label="Permalink to “隐式标签名（可选）”">​</a></h3><p>在部分上下文里可省略标签名，例如 <code>.box</code> 在 HTML 里常展开为带 <code>class=&quot;box&quot;</code> 的 div（依赖 Emmet 的隐式规则）。</p><h3 id="按-tab-不展开时排查" tabindex="-1">按 <code>Tab</code> 不展开时排查 <a class="header-anchor" href="#按-tab-不展开时排查" aria-label="Permalink to “按 Tab 不展开时排查”">​</a></h3><ol><li>设置里搜 <code>Emmet: Trigger Expansion On Tab</code>，确认已开启。</li><li>光标放在缩写<strong>末尾</strong>再按 Tab。</li><li>文件语言模式应是 <strong>HTML</strong>（右下角语言标识）。</li><li>或者重启一下编辑器。</li></ol><h3 id="其它与-html-相关的习惯" tabindex="-1">其它与 HTML 相关的习惯 <a class="header-anchor" href="#其它与-html-相关的习惯" aria-label="Permalink to “其它与 HTML 相关的习惯”">​</a></h3><ul><li><strong>自动闭合标签</strong>：设置里 <code>html.autoClosingTags</code>。</li><li><strong>重命名配对标签</strong>：可安装「Auto Rename Tag」类扩展，改一侧标签名另一侧同步。</li><li><strong>格式化</strong>：<code>Shift + Alt + F</code>（Windows）整理缩进。</li><li><strong>用户代码片段</strong>：<code>文件 → 首选项 → 配置用户代码片段</code>，自定义整块 HTML 模板。</li></ul><p>在 <strong>Vue / React 模板</strong> 中使用 Emmet 时，若默认不生效，可在 <code>settings.json</code> 里用 <code>emmet.includeLanguages</code> 把对应语言映射到 <code>html</code>（按实际技术栈配置）。</p>',22)])])}const b=t(l,[["render",r]]);export{g as __pageData,b as default};
